#!/usr/bin/env python3
"""Render docs/expansion/audit/inventory.md from inventory.csv + summary.json (both written by build_inventory.py)."""
import csv, json, sys, collections
out = sys.argv[1] if len(sys.argv) > 1 else "docs/expansion/audit"
R = list(csv.DictReader(open(f"{out}/inventory.csv", encoding="utf-8")))
S = json.load(open(f"{out}/summary.json"))
ST = S["statuses"]
def tab(key):
    d = ST[key]; return " | ".join(f"{k} {d.get(k,0)}" for k in ("APPROVED","PRESENT","NEEDS REVIEW","BLOCKED","MISSING","NOT YET LOCATED"))
def rng(nums):
    nums = sorted(int(n) for n in nums); o=[]; i=0
    while i < len(nums):
        j=i
        while j+1 < len(nums) and nums[j+1]==nums[j]+1: j+=1
        o.append(str(nums[i]) if i==j else f"{nums[i]}-{nums[j]}"); i=j+1
    return ", ".join(o) or "none"
cards = lambda pred: [r["card_number"] for r in R if pred(r)]
zips = S["zips"]
L = []
a = L.append
a("# Expansion cards #57-141: master inventory\n")
a(f"Generated by `scripts/expansion-audit/build_inventory.py` + `write_report.py` from `{S['branch']}` @ `{S['branch_head'][:10]}`. READ-ONLY audit: nothing was imported, promoted or altered; no image is committed. The machine-readable inventory is `inventory.csv` (one row per card, 73 columns).\n")
a("## Method\n")
a("""* Branch contents were read with `git archive` into a temp directory outside the repo and never checked out. Related branches (`claude/botanical-catalog-stage-1`, `prep-expansion`, `exp`, `claude/production-system-v1`, `backup/*`) were searched by **file path only** for the species slug; counts are in the CSV column `paths_naming_species_on_other_branches`.
* Statuses are exactly: PRESENT, APPROVED, MISSING, NEEDS REVIEW, BLOCKED, NOT YET LOCATED. **APPROVED** is used only where a commit message or file in the branch records owner approval, and the quote is in the row (`owner_approval_quote`, `sprite_approval_quote`). Everything else that exists is PRESENT. NEEDS REVIEW = present but the record itself says review is pending (or a check failed). BLOCKED = cannot move forward until something else happens.
* Each card's `approved_final/provenance.json` per-file sha256 was recomputed against the files in the tree. The seven `source.files` hashes in `expansion-cards.json` were recomputed against `expansion/source/`.
* "Back-field content" is taken from each card's `profile-draft.json` (record **plus** owner text-overrides, as rendered); where it differs from `expansion-cards.json` the differing fields are listed and each diff is checked to be explained by an entry in `expansion/text-overrides.json`.
* Nothing botanical was inferred. A field the data does not contain is MISSING, not guessed.
""")
a("## Totals (85 cards)\n")
a("| Item | " + " | ".join(("APPROVED","PRESENT","NEEDS REVIEW","BLOCKED","MISSING")) + " |\n|---|---|---|---|---|---|")
labels = [("main_image_status","Main botanical image"),("tall_preview_status","Tall/preview image (standalone file)"),("pixel_icon_status","Native 21-24px pixel icon"),("card_front_status","Assembled front"),("card_back_status","Assembled back"),("card_pdf_status","Card PDF"),("card_assembled_status","Card as a whole (front+back+PDF; APPROVED = assembled on a package whose commit says approved)"),("card_base_status","Art-less card-base"),("sprite_files_status","Garden sprite + 3 growth stages"),("sprite_brief_status","sprite-brief.json"),("profile_draft_status","profile-draft.json"),("back_fields_status","Six back fields"),("safety_caution_review_status","Safety caution review"),("references_status","Citations"),("challenge_fields_status","Rarity/XP/season/stats"),("qc_status","QC (publication status)"),("implementation_status","Implementation")]
for k,l in labels:
    d=ST[k]; a(f"| {l} | " + " | ".join(str(d.get(x,0)) for x in ("APPROVED","PRESENT","NEEDS REVIEW","BLOCKED","MISSING")) + " |")
a("\nIdentification features, lookalikes and descriptive habitat: **MISSING for all 85** (no such fields exist in the record, profile-drafts or source files). `profile-draft.json` itself lists plant-page copy as a still-needed step.\n")
a("## Numbering and identifiers\n")
a(f"* Integration holds: printed cards #1-45 (`herbs.json`; #46 icon cheat sheet and #47 disclaimer are non-herb cards), digital Field Cards #{S['field_cards'][0][1]}-{S['field_cards'][-1][1]} (`field-cards.ts`, nine cards). The expansion is #57-141, contiguous: **{S['count']} cards, no gaps, no duplicate numbers, no duplicate ids**. Numbering was not changed or assumed: the importer's own header, QA file and numbers agree.")
a(f"* **Collisions with integration (id, number, scientific name, sprite id, genus of a `spp.` card): {'none' if not S['collisions'] else S['collisions']}.** Cards in a genus that already has a card (different species) are noted in `notes`.")
a("* The earlier 86-card numbering (`evidence/expansion-86.json`, `expansion-queue.txt` on `exp` / `production-system-v1`) is **superseded** by this 85-card list (Blue Mistflower removed; `docs/expansion-cards.md` states the photo-production queue was built on the old numbering). Provenance for #72-75 notes \"zip used old numbering; mapped by species\". Anything keyed by the old numbers must be remapped by scientific name.")
a("* Genus-level (`spp.`) identities: " + (rng(S['genus_level']) if S['genus_level'] else "none; all 85 are binomials (species level)") + ".\n")
a("## Source hash verification\n")
a("| File | Recorded | Actual | Result |\n|---|---|---|---|")
for f,w,ac,s in S["source_hashes"]:
    a(f"| `{f.split('/')[-1]}` | `{w[:12]}` | `{(ac or 'n/a')[:12]}` | {'MATCH' if s=='PRESENT' else 'MISMATCH/MISSING'} |")
a("\nPer-card `approved_final/provenance.json` hashes: " + ("**no mismatches**" if not S["hash_issues"] else str(S["hash_issues"])) + " across all cards with a provenance file (see `provenance_hashes_verified`). Cards #57-61 have no `approved_final`; their artwork hashes live in `expansion/assets/<id>/assets.json`.\n")
a("## Findings\n")
n_ai = sum('AI derivative' in r['notes'] for r in R)
a(f"""1. **Safety review is pending on every card (85/85).** Every caution is marked \"SHORT CARD COPY — final botanical/safety review pending\"; the source package itself says do not publish. {len(S['generic_caution'])} cards carry only a generic or family-level line ('Identify positively…' or 'Daisy-family allergy possible.'): {rng(S['generic_caution'])}. All 85 are therefore BLOCKED for promotion regardless of artwork.
2. **Citations are thin.** Only {S['citation_totals'][0]} links across {sum(1 for r in R if int(r['real_citations_n'])>0)} cards are recorded as real direct references (`isCitation: true`, still marked \"claim matching still needed\"); {S['citation_totals'][1]} are literature **search links** (`isCitation: false`). {len(S['no_citation'])} cards have no direct citation and no carried-over URL at all. Carried-over URLs (24 cards) are, per the record's own note, supporting only their documented subject, not the whole card. The package cites `PlantDex_Usable_Parts_Guide_57-142.pdf` as primary guide for usable parts; **that PDF is not in any branch (NOT YET LOCATED)**.
3. **Six cards have no main botanical image file:** #{rng(S['missing_main'])}. #97-101 were delivered as \"enlarged fronts\" with no cutouts (commit 419ae2e); #129 has no main cutout in `approved_final` (reason not recorded). Their fronts exist but the cutout cannot be reused.
4. **Standalone tall/preview images exist for only 12 cards** (the ten with `expansion/assets/` folders, plus #105 and #106 via `tall_cutout_used.png`, which the commits say were rebuilt from hi-res tall cutouts); for the other 73 the preview exists only baked into `back.png`/`back_final.png`.
5. **Pixel icons: all 85 present, all within 21-24px square** (`pixel_icon_dim` column). Only #57-61 record explicit owner approval of icons (\"ChatGPT handoff, owner-approved #57-61\"). The icon palette/gradient checks are warnings only in `asset-spec.json`; the #57-61 icons carry 100+ colours (recorded in `assets.json` warnings).
6. **Garden sprites exist for 5 cards (#57-61) only**, with 3 growth stages each (`expansion/sprites/_build`), 80 missing. Approval is recorded only in the commit message of f3861d1 (\"record owner approval of the five sprites\"); **a later commit (ec7d7c1, a card-back render) overwrote the approval text in all five `sprite-brief.json` files back to \"BRIEF ONLY - no sprite has been authored\"**, so the file contradicts the commit. The other 80 cards have no `sprite-brief.json` either.
7. **Approval evidence is sparse.** APPROVED assembled-card status for {len(S['approved_cards'])} cards ({rng(S['approved_cards'])}) rests on commit subjects such as \"assembled on approved finals\" (V28, V10, V15 packages). #57-61 record owner approval of main/pixel/tall in `assets.json`. No file records approval of any card's safety text, botanical accuracy, regions or sources. Owner text edits (healing traits etc., `text-overrides.json`, all marked `by: owner`) are edits, not approvals.
8. **AI-derived art:** {n_ai} cards use a main image whose filename marks it generated/reconstructed/edited (`main_generated_cutout_used`, `main_ai_reconstruction_used`, `main_cutout_edit`); #57-61 are recorded `origin: ai_generated_derivative`, `botanical_review_required: true`. Whether the remaining `main_cutout_used` files are photo cutouts is not recorded per card.
9. **Provenance gaps:** zip package for #67-71 not recorded; zip hash unavailable for #117-121 (zip no longer on disk); #57-61 have no zip at all (assets.json only). Source zips are **not in the repo for any batch** (see below). For the photograph-based cards, iNaturalist photo/licence manifests are not in the expansion tree; the other branches hold photo evidence for only a handful of species (see CSV column), so photo licensing/attribution for most main images is NOT YET LOCATED.
10. **Card-base:** art-less bases exist for 75 cards (#62-66, #72-141); missing for #{rng(cards(lambda r: r['card_base_status']=='MISSING'))}. #57-61 predate the card-bases folder and #67-71 were assembled directly from supplied finals.
11. **Back text drift:** every card has owner overrides in `text-overrides.json` and `profile-draft.json` differs from `expansion-cards.json` for those fields, as designed. No diff is unexplained by an override ({'none unexplained' if not S['unexplained_back'] else rng(S['unexplained_back'])}). 80 cards have both `approved_final/back_final.png` (the as-supplied back) and owner overrides, so that file predates the edits; `back.png` is the re-render. The master spreadsheet/JSON was not updated to match (text-overrides says so).
12. **Regions are provisional** on all 85 (\"Provisional ecology-based; confirm range before quest release\"). Region codes are the draft PlantDex ten-region model. They are carried in the CSV as `regions_PROVISIONAL` only.
13. **Challenge/progression fields are internally consistent:** rarity/XP match the deck table (Common 100, Uncommon 175, Rare 300, Epic 500), stats are 1-5, season uses the app vocabulary after mapping Fall to autumn, use icons are within the allowed twelve. Distribution: rarity {S['rarity']}, season {S['season']}. Only one winter card (#{cards(lambda r: r['season']=='winter')[0] if cards(lambda r: r['season']=='winter') else 'n/a'}).
14. **Implementation:** nothing is in `CATALOGUE`, `herbs.json` or `public/` (by design; enforced by `expansion-cards.test.ts`). Promotion needs: safety review, a `collectionId`, web derivatives, sprite, plant-page copy, and an owner decision.
""")
a("## Missing source packages the owner must transfer\n")
a("No original zip or source folder is in git for any batch; only the extracted finals and provenance JSON are. To rebuild, re-verify, or re-derive any card, these are needed (hash = what provenance recorded; verify on receipt):\n")
a("| Package | Cards | sha256 recorded |\n|---|---|---|")
for z,v in zips.items():
    h = v["sha256"] if len(str(v["sha256"]))==64 else "NOT RECORDED"
    a(f"| `{z}` | {rng(v['cards'])} | `{h}` |")
a("""
Also needed / NOT YET LOCATED:

* `PlantDex_Usable_Parts_Guide_57-142.pdf`: the user-supplied guide the record cites as primary source for usable parts (cited per card in `review.references.primaryProvidedGuide`).
* The #57-61 handoff zip (ChatGPT, owner-approved) — only its extracted contents are in `expansion/assets/_batches/57-61/`.
* The #67-71 V28 package zip (name not recorded; `expansion/assets/_batches/67-71` holds one file).
* The earlier 86-card healing-traits spreadsheet (removed from the repo; superseded by the master).
* Original photographs and their iNaturalist/licence manifests for the expansion species (the instruction in the #57-61 handoff says to keep these). On the other branches, photo sets exist only for #57, 86, 102, 115 and 136 (large `evidence/photos/<species>` folders) plus small selection-study files for #58-76; none for #77-141 apart from those.
* Updated master (JSON/CSV/xlsx) reflecting the owner text-overrides, if the owner wants the source of truth corrected.
* Sprites/briefs for #62-141 (not created yet; not a transfer item, listed as a gap).
""")
a("## Biggest gaps (ranked)\n")
a("1. Safety/botanical review: 85/85 pending; 25 cautions generic.\n2. Sources: 21 real citations for 7 cards; 78 cards have no direct citation.\n3. Sprites: 80/85 missing.\n4. Identification features, lookalikes, descriptive habitat: absent for all 85.\n5. Main image file missing for 6 cards (#97-101, #129); standalone tall previews for 73.\n6. Source zips and photo licence manifests not in the repo.\n7. Owner approval recorded only for #57-61 assets and sprites and the assembled finals of 18 cards.\n")
a("## Files\n\n* `inventory.csv` - the inventory (column meanings are the headers; `*_status` columns use the six statuses).\n* `summary.json` - machine-readable totals.\n* Rebuild: see header of `scripts/expansion-audit/build_inventory.py`.\n")
open(f"{out}/inventory.md","w",encoding="utf-8").write("\n".join(L))
print("wrote", f"{out}/inventory.md")
